import{_ as a}from"./chunks/20-cli-doctor.DOzHD6qf.js";import{_ as s,o as t,c as i,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function l(r,e,d,h,p,c){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Clone the repository (<code>git clone https://github.com/TerminalDZ/vidcreat.git</code>) or unpack a release archive anywhere you like (for example <code>Documents/ReelForge</code>). Avoid folders synced by OneDrive or iCloud for faster renders.</p><h2 id="windows-10-11" tabindex="-1">Windows 10 / 11 <a class="header-anchor" href="#windows-10-11" aria-label="Permalink to &quot;Windows 10 / 11&quot;">​</a></h2><ol><li>Install <strong>Node.js 22 LTS</strong> from <a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a> (keep the default options). If it is missing, the installer can install it for you with <code>winget</code>.</li><li>Double-click <strong><code>install.bat</code></strong>. It will: <ul><li>check Node.js,</li><li>offer to install <strong>ffmpeg</strong> with <code>winget</code> (answer <strong>Y</strong>),</li><li>install ReelForge&#39;s dependencies,</li><li>download the pinned Chromium browser used for rendering,</li><li>run a full environment check.</li></ul></li><li>Double-click <strong><code>start.bat</code></strong> to open the dashboard.</li></ol><blockquote><p>If Windows SmartScreen warns about the script, choose <strong>More info → Run anyway</strong>. If ffmpeg was just installed, close and reopen <code>start.bat</code> so Windows picks up the new PATH.</p></blockquote><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li><p>Install <strong>Node.js 22 LTS</strong> from <a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a> and <strong>Homebrew</strong> from <a href="https://brew.sh" target="_blank" rel="noreferrer">https://brew.sh</a>.</p></li><li><p>Open <strong>Terminal</strong> in the ReelForge folder (Finder → right-click the folder → <em>New Terminal at Folder</em>) and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>Answer <strong>Y</strong> when it offers <code>brew install ffmpeg</code>.</p></li><li><p>Double-click <strong><code>ReelForge.command</code></strong> (or run <code>./start.sh</code>) to open the dashboard.</p></li></ol><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # add --yes to accept every prompt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # opens the dashboard</span></span></code></pre></div><p>The installer uses your package manager (<code>apt</code>, <code>dnf</code>, <code>pacman</code> or <code>zypper</code>) for ffmpeg and can install Chromium&#39;s system libraries (it asks for <code>sudo</code>).</p><h2 id="from-source-developers" tabindex="-1">From source (developers) <a class="header-anchor" href="#from-source-developers" aria-label="Permalink to &quot;From source (developers)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/TerminalDZ/vidcreat.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vidcreat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><p>The <a href="./contributing.html">contributing guide</a> covers the full development setup on each system.</p><h2 id="check-your-setup-at-any-time" tabindex="-1">Check your setup at any time <a class="header-anchor" href="#check-your-setup-at-any-time" aria-label="Permalink to &quot;Check your setup at any time&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Windows: reelforge.cmd doctor</span></span></code></pre></div><p>It checks Node.js, ffmpeg (version, encoders and filters), Chromium and the bundled fonts, and prints the exact fix for anything missing. The dashboard shows the same check as the status pill in the top bar.</p><p><img src="`+a+`" alt="reelforge doctor"></p><h2 id="optional-speech-models" tabindex="-1">Optional speech models <a class="header-anchor" href="#optional-speech-models" aria-label="Permalink to &quot;Optional speech models&quot;">​</a></h2><p>Automatic cue alignment works without any download (pause detection over the known script). For word-level accuracy with music in the background, install the optional speech models once (about 180 MB):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # downloads Whisper and Silero VAD into your user cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # shows what is installed</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>The dashboard says “setup issues”</td><td>Click the pill: each failed check shows its fix. Most often ffmpeg is missing.</td></tr><tr><td><code>ffmpeg not found</code></td><td>Windows: <code>winget install Gyan.FFmpeg</code>; macOS: <code>brew install ffmpeg</code>; Linux: your package manager. Then open a new terminal or <code>start.bat</code>.</td></tr><tr><td>“Cannot launch Chromium”</td><td>Run <code>reelforge doctor --fix</code>. On Linux, run the installer again and accept the system libraries prompt.</td></tr><tr><td>ffmpeg installed but still not found (Windows)</td><td>Close every terminal and <code>start.bat</code>, then reopen: Windows only picks up the new PATH in new windows.</td></tr><tr><td><code>pnpm</code> is not recognized</td><td>Run <code>corepack enable</code> once (Node.js 22 ships Corepack), then open a new terminal.</td></tr><tr><td>Renders are slow or fail with disk errors</td><td>Move the folder out of OneDrive or iCloud and keep about 2 GB free for temporary files.</td></tr></tbody></table><p>More answers are in <a href="./faq.html">FAQ and troubleshooting</a>.</p><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>If you cloned the repository, run <code>git pull</code>, then run the installer again (or <code>pnpm install &amp;&amp; pnpm build</code>).</p><p>If you downloaded a release archive, download the new version from the <a href="https://github.com/TerminalDZ/vidcreat/releases" target="_blank" rel="noreferrer">releases page</a>, unpack it next to the old one, copy your <code>episodes/</code> folder (and any custom <code>themes/</code> or <code>presets/</code>) into the new folder, then run the installer again. Your episodes are plain files: nothing else needs migrating.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><p>Delete the ReelForge folder. The Chromium download lives in your user cache folder (<code>%LOCALAPPDATA%\\ms-playwright</code> on Windows, <code>~/Library/Caches/ms-playwright</code> on macOS, <code>~/.cache/ms-playwright</code> on Linux) and can be deleted too. The optional speech models from <code>reelforge align --setup</code> live in <code>reelforge</code> inside the same cache folder (<code>%LOCALAPPDATA%\\reelforge</code>, <code>~/Library/Caches/reelforge</code>, <code>~/.cache/reelforge</code>).</p>`,28)])])}const m=s(n,[["render",l]]);export{u as __pageData,m as default};
